shader_body
{
uv = 0.5 + (uv-0.5)*0.88;
vec2 d = (vec2(1.0)/uTexSize) * 4.0;
vec3 dx = ( GetBlur1(uv + vec2( 1.0 , 0.0 )*d) - GetBlur1(uv-vec2( 1.0 , 0.0 )*d).xy );
vec3 dy = ( GetBlur1(uv + vec2( 0.0 , 1.0 )*d) - GetBlur1(uv-vec2( 0.0 , 1.0 )*d).xy );
//    vec2 uv_dy = uv + vec2(dy.y,-dx.y)*0.2*rad_hq;
//    vec3 c1 = GetBlur1(uv_dy).y;
float grad_y = length(vec2(dx.y,dy.y));
vec3 c2 = grad_y*0.8;
vec3 emboss = (dx - dy*0.2)*0.8 + 0.5;
vec2 uv_light1 = 1.0 - (vec2(q4,q8)*vec2( 1.0 ,-1) + vec2( 0.0 , 1.0 ));
vec3 light1_dy = 1.04- pow(length( uv + vec2(dx.y,dy.y) * 2.0 - uv_light1),0.35);
vec3 light1_dx = 1.04- pow(length( uv + vec2(dx.x,dy.x) * 2.0 - uv_light1),0.35);
vec3 plastic = mix( 0.0 ,light1_dy * 2.0,c2 * 4.0);
ret = -plastic * 0.0 + emboss.y*0.3 + light1_dy*0.5;
ret = GetPixel(uv).y*ret * 2.0;
ret = mix(GetPixel(uv - vec2(dy.x,-dx.x)*0.2 + vec2(dx.y,dy.y)*0.2).x*(vec3( 0.0 , 0.0 , 2.0)+light1_dy*vec3( 2.0 , 1.0 ,-2)),
mix(hue_shader,vec3( 2.0 ,0.8, 0.0),GetPixel(uv - vec2(dx.z,dy.z)*0.06 + vec2(dx.y,dy.y)*0.3).z * 16.0),pow(ret, 2.0 ));
}

void main() {
  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  vec2 uv_x, uv_y, uv_z, uv_echo;
shader_body
{
